class ScratchGame extends GameEngine{constructor(t,s,e){super(t,"scratch",s),this.prizes=e,this.canvas=null,this.ctx=null,this.isScratching=!1,this.scratchAmount=0,this.revealThreshold=s.reveal_threshold||.5}render(t){const s=`\n      <div class="game-container">\n        <div class="game-header">\n          <h2>🎫 Cào Quà</h2>\n          <p>Cào để phát hiện giải thưởng</p>\n          <div class="timer" id="timer">0s</div>\n        </div>\n\n        <div class="scratch-game-wrapper">\n          <div class="scratch-card">\n            <div class="scratch-revealed">\n              <div class="prize-emoji">${this.prizes[0].icon||"🎁"}</div>\n              <div class="prize-name">${this.prizes[0].name}</div>\n              <div class="prize-value">💰 ${(this.prizes[0].cash_amount||0).toLocaleString()}đ</div>\n            </div>\n            <canvas id="scratchCanvas" class="scratch-canvas" width="300" height="350"></canvas>\n          </div>\n        </div>\n\n        <div class="scratch-info">\n          <p>Cào <strong>${Math.round(100*this.revealThreshold)}%</strong> để phát hiện</p>\n          <div class="scratch-progress">\n            <div class="scratch-progress-bar" id="progressBar"></div>\n          </div>\n          <p id="progressText">0%</p>\n        </div>\n      </div>\n    `;document.getElementById(t).innerHTML=s,this.canvas=document.getElementById("scratchCanvas"),this.ctx=this.canvas.getContext("2d"),this.ctx.fillStyle="#d4af37",this.ctx.fillRect(0,0,this.canvas.width,this.canvas.height),this.ctx.fillStyle="#a0860f",this.ctx.font="bold 18px Arial",this.ctx.textAlign="center",this.ctx.fillText("CÀO ĐỂ NHẬN",this.canvas.width/2,this.canvas.height/2-20),this.ctx.fillText("THƯỞNG",this.canvas.width/2,this.canvas.height/2+20),this.attachEventListeners(),this.startTimer()}attachEventListeners(){this.canvas.addEventListener("mousedown",()=>{this.isScratching=!0}),this.canvas.addEventListener("mouseup",()=>{this.isScratching=!1}),this.canvas.addEventListener("mousemove",t=>this.scratch(t)),this.canvas.addEventListener("touchstart",()=>{this.isScratching=!0}),this.canvas.addEventListener("touchend",()=>{this.isScratching=!1}),this.canvas.addEventListener("touchmove",t=>this.scratch(t))}scratch(t){if(!this.isScratching)return;const s=this.canvas.getBoundingClientRect();this.ctx.clearRect((t.touches?t.touches[0].clientX:t.clientX)-s.left-25,(t.touches?t.touches[0].clientY:t.clientY)-s.top-25,50,50),this.scratchAmount+=2500;const e=this.scratchAmount/(this.canvas.width*this.canvas.height),n=Math.min(100,Math.round(100*e));document.getElementById("progressBar").style.width=n+"%",document.getElementById("progressText").textContent=n+"%",e>=this.revealThreshold&&(this.canvas.style.pointerEvents="none",setTimeout(()=>this.endGame(0),300))}endGame(t){this.state="completed";const s=this.prizes[t||0];this.selectedPrize=s;const e=this.getCompletionTime();fetch("/api/game/result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({session_code:this.sessionCode,game_type:this.gameType,prize_id:s.id,completion_time:e})}).catch(t=>{}),this.showResultScreen(s)}showResultScreen(t){const s=t.color||"#8b5cf6",e=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${s}">🎉</div>\n        <h2 class="result-title">Chúc Mừng!</h2>\n        <p class="result-message">Bạn đã thắng giải thưởng</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 2.5rem; margin-bottom: 10px;">${t.icon||"🎁"}</div>\n          <strong style="color: ${s}; font-size: 1.4rem;">${t.name}</strong>\n          ${t.cash_amount?`<p>💰 ${t.cash_amount.toLocaleString()}đ</p>`:""}\n          <p style="font-size: 0.9rem; opacity: 0.8;">Rarity: <strong>${t.rarity||"common"}</strong></p>\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            ✅ Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="shareResult()">\n            📤 Chia Sẻ\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=e}startTimer(){this.startTime=Date.now();const t=setInterval(()=>{const s=Math.floor((Date.now()-this.startTime)/1e3),e=document.getElementById("timer");e?e.textContent=s+"s":clearInterval(t)},1e3)}}